import app from 'flarum/forum/app';
import Icon from 'flarum/common/components/Icon';
import { NS } from '../../common/levels';
/** A requirement list: met or not, a bar, "have / need". */
export default function Rows(rows) {
  return rows.map(row => {
    const pct = row.upTo ? row.met ? 100 : 0 : row.need > 0 ? Math.min(100, Math.round(row.have / row.need * 100)) : 100;
    return m("div", {
      className: 'TrustRow' + (row.met ? ' TrustRow--met' : '')
    }, m(Icon, {
      name: row.met ? 'fas fa-circle-check' : 'far fa-circle',
      className: "TrustRow-icon"
    }), m("span", {
      className: "TrustRow-label"
    }, app.translator.trans(`${NS}.forum.req.${row.key}`, {
      need: row.need
    })), m("span", {
      className: "TrustRow-meter",
      "aria-hidden": "true"
    }, m("b", {
      style: {
        width: pct + '%'
      }
    })), m("span", {
      className: "TrustRow-num"
    }, row.key === 'not_suspended' ? '' : row.upTo ? `${row.have} / ≤ ${row.need}` : `${row.have} / ${row.need}`));
  });
}
flarum.reg.add('ernestdefoe-trust-levels', 'forum/components/Rows', Rows);